custom_css:
/*
《 𝐒𝐀𝐓𝐈𝐒 》
作者: 睏暝@woolenbrave
版本：v3
此美化免費發布於旅程、尾巴鎮DC，請勿商用與二傳，二改請保留代碼作者標註。
*/

/*💠==字體==💠*/
@import url("https://fontsapi.zeoseven.com/79/main/result.css");
@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&display=swap');
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

body, select, code, .text_pole, #send_textarea, #chat .edit_textarea {
  font-family: var(--MainFont) !important;
}
/*💠==全局==💠*/
:root {
    /* 文字 */
  --MainFont: "Lora", "Clear Han Serif", serif; /* 正文字體 */
  --SecFont: "Noto Serif CJK";/* 裝飾字體 */
  --TextSize: 1em; /*正文字體大小*/
  --LetterSpacing: 0.5px; /*字距*/
  --TextPadding: 10px; /*正文與聊天框邊界的距離*/
  --LineHeight: 1.7em; /*行高*/
  --LineSpace: 1.3em; /*段距*/
  --TextAlign: justify; /*對齊方式 justify 或 left*/
  --Indent: 2em; /*首行縮排*/

    /* 主題元素顏色 */
  --ItemColor: var(--SmartThemeUnderlineColor);

    /* 頂欄&底欄圖標 */
  --TopBarIconColor: var(--ItemColor); /*頂欄&底欄圖標顏色*/
  --TopBarIconOpacity: 0.3;  /* 頂欄&底欄圖標透明度 */
  --TopBarIconSize: 19px; /*頂欄圖標大小*/
  --BottomBarIconSize: 21px; /* 底欄圖標大小 */

    /* 背景顏色 */
  --TopBarColor: var(--SmartThemeChatTintColor); /*頂底欄*/
  --PanelColor: var(--SmartThemeChatTintColor);/*左右欄*/   
  --PanelColorPhone: var(--SmartThemeBlurTintColor);/*手機左右欄*/

  --SmartThemeRadius: 4px;/* 全局圓角 */
  --Scrollbar: 5px; /*滾動條寬度*/
  --ChatBorder: 1px solid  color-mix(in srgb, var(--ItemColor) 15%, transparent);/*聊天氣泡外框*/
}

/*💠背景圖片調整(拿掉標註使用)*/
/*#bg1 {
    opacity: 0.9 !important;
    filter: brightness(0.4) blur(0px) grayscale(20%) contrast(95%) !important;
    box-shadow: inset 0 0 100px 50px rgba(0, 0, 0, 0.0) !important;}*/



/* 🪲正文與聊天氣泡 */

/* 聊天氣泡邊距 */
#chat { padding: 8px 0px 8px var(--Scrollbar);}

/* 手機端聊天框 隱藏滾動條+對齊 */
@media screen and (max-width: 768px) {
    #chat::-webkit-scrollbar { display: none !important;}
    #chat { padding: 8px 5px !important; }}

#chat .mes {
  box-shadow: inset 0 0 8px color-mix(in srgb, var(--ItemColor) 20%, transparent) !important;
  margin-top: 4px;
  flex-direction: column;
  align-items: center;
  border-radius: var(--SmartThemeRadius) !important;
  padding-top: 240px !important; /*😡*/
  border: var(--ChatBorder) !important;
  position: relative !important;
  transform: none !important; 
  perspective: none !important;
  contain: layout; 
}

.mes_block {
  width: 100%;
  padding-left: 0;
  position: static !important;
  transform: none !important;
}

.mes_text {
  font-size: var(--TextSize);
  text-align: var(--TextAlign);
  width: 100% !important;
  line-height: var(--LineHeight);
  letter-spacing: var(--LetterSpacing);
  padding: 5px var(--TextPadding) 5px var(--TextPadding) !important;
}

.mes_text p {
    margin-bottom: var(--LineSpace) !important;
    text-indent: var(--Indent);
}

.mes_text p:last-child {
    margin-bottom: 0px !important;
}

/* 引用塊 */
.mes_text blockquote {
  background: transparent;
  padding: 20px 20px;    
  border-radius: 10px;
  margin-bottom: 20px;
  border-left: 3px double color-mix(in srgb, var(--ItemColor) 60%, transparent);
  border-right: 3px double color-mix(in srgb, var(--ItemColor) 60%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--ItemColor) 20%, transparent) !important;
  transition: border 0.6s ease, box-shadow 0.6s ease-out;
}

.mes_text blockquote:hover {
  border-left: 3px double color-mix(in srgb, var(--ItemColor) 100%, transparent);
  border-right: 3px double color-mix(in srgb, var(--ItemColor) 100%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--ItemColor) 60%, transparent) !important;
}

/* 代碼包裹 by @Junezz 復古MacOs */
  code {
    background-color: transparent !important;
    color: var(--SmartThemeBodyColor) !important;
    font-family: var(--MainFont);
    border: 1px solid color-mix(in srgb, var(--ItemColor) 30%, transparent);
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 30%, transparent) !important;
    font-size: calc(var(--mainFontSize)* 0.98);
    padding: 0px 3px;
    line-height: var(--LineHeight) !important;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0px;
}

/* 選取文本樣式 by@potato_juice9 */
.mes_text ::selection {
    background: var(--ItemColor) !important;
    color: var(--SmartThemeBlurTintColor);
}

/* 聊天氣泡底端文字 */
.mes_block::after {
    content: "𖤓—⊹ 𝔐𝔢𝔪𝔢𝔫𝔱𝔬 𝔐𝔬𝔯𝔦 ⊹—𖤓";
    display: block;
    text-align: center;
    font-size: 13px;
    color: var(--ItemColor);
    margin-top: 20px;      
    margin-bottom: 20px;      
    opacity: 0.3;
}

/* 🪲切換消息 */
.swipeRightBlock,
.swipe_left {  
  right: 10px !important;
  color: var(--SmartThemeUnderlineColor);
  bottom: 12px;
}
.swipe_left {
  bottom: 27px;
}

/*切換消息裝飾🍊*/
.swipe_left::before,
.swipe_right::before {
  content: ''; 
  display: inline-block;
  width: 15px;
  height: 15px; 
  background-image: url('https://pub-ab57b744470342a2aea5107d958a034e.r2.dev/satis/swordwhite.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  vertical-align: middle;
}

.swipe_left, .swipe_right {
  opacity: 0.3 !important;
}

.swipe_left::before {
  transform: rotate(-165deg);
}

.swipe_right::before {
  transform: rotate(85deg);
}

/*🪲頭像*/

body.square-avatars .avatar, body.square-avatars .mes .avatar img {
    border-radius: 50% !important;
}

body.square-avatars .avatar, body.square-avatars .avatar img {
  border-radius: var(--SmartThemeRadius) !important;
}

.avatar img {
    border: 1px solid color-mix(in srgb, var(--ItemColor), transparent 70%) !important;
}

.mes .avatar {
    position: absolute !important;
    left: 50% !important;
    top: -160px !important; /*😡*/
}

/* 聊天訊息頭像 */
.mes .avatar img {
    position: absolute;
    height: 101px !important;
    width: 85px !important;
    border-radius: 50% !important; 
    border: 4px double color-mix(in srgb, var(--ItemColor) 80%, transparent) !important; 
    box-shadow: 0 4px 8px rgba(0,0,0,0.6) !important;
    padding: 2px !important;
    background-color: var(--SmartThemeChatTintColor)!important;
    object-fit: cover !important;
    transform: translateX(-50%);
    transition: transform 0.6s ease-out, box-shadow 0.6s ease-out !important;
    z-index: 10 !important;
}

.mes .avatar img:hover {
    transform: translateX(-50%) translateY(-8px) !important;
    box-shadow: 0 10px 20px rgba(0,0,0,0.6) !important;
}

.mesAvatarWrapper {
  position: static !important;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.mes .avatar {
    position: relative !important;
}

/* 頭像裝飾🍇* */
.mes .avatar::after {
    content: "";
    display: block;
    background-image: url('https://pub-ab57b744470342a2aea5107d958a034e.r2.dev/satis/crown.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;   
    width: 100px;
    height: 43px;
    position: absolute;
    top: -34px;  
    transform: translateX(-50%);
    z-index: 0 !important;
    pointer-events: none;
    transition: transform 0.6s ease-out !important; 
}

.mes .avatar:hover::after {
    transform: translateX(-50%) translateY(-8px) !important;
}

/*🪲聊天氣泡頂部元素*/

.mes_buttons, .mes_edit_buttons, .mes_ghost, .mes .name_text, .mesIDDisplay, .mes_timer,
.tokenCounterDisplay,.icon-svg,.timestamp {
  color: var(--SmartThemeBodyColor);
  position: absolute !important;
  z-index: 20  !important;
}

/* 🍺角色名字 */
.mes .name_text {
  top: 198px; /*😡*/
  left: 50%;
  letter-spacing: 1px;
  transform: translateX(-50%);
  font-size: 16px;
  font-family: var(--SecFont);
  opacity: 1;
  color: var(--ItemColor) !important;
}

.mes .name_text::before {
  content: "-";
  margin-right: 8px;
  display: inline-block;
  transform: scaleX(-1) translateY(-1.5px);
  opacity: 0.7;
}

.mes .name_text::after {
  content: "-";
  margin-left: 8px;
  display: inline-block;
  transform: translateY(-1.5px);
  opacity: 0.7;
}

/* 🍺日期時間 */
.timestamp {
    top: 219px; /*😡*/
    font-size: 12px;
    letter-spacing: 1px;
    transform: translateX(-50%);
    left: 50%;
    padding: 3px 10px;
    opacity: 0.9 !important;
    transition: opacity 0.6s ease, box-shadow 0.6s ease-out;
    font-family: var(--SecFont);
    color: var(--ItemColor);
}

.mes_ghost:hover, .mes .name_text:hover, .timestamp:hover {
  opacity: 1 !important;
  text-shadow: 0 0 16px color-mix(in srgb, var(--ItemColor) 100%, transparent) !important;
}

.mes_reasoning_actions,
.mes_ghost,
#chat .mes_buttons .mes_button,
#chat .mes_edit_buttons .menu_button,
#chat .favorite-toggle-icon {
    color: var(--ItemColor) !important;
    opacity: 0.4 !important;
    transition: opacity 0.6s ease;
    filter:  none;
}

#chat .mes_edit_buttons .menu_button {
    color: var(--ItemColor) !important;
    opacity: 0.8 !important;
    transition: opacity 0.6s ease;
    filter:  none;
}

.mes_ghost:hover,
#chat .mes_buttons .mes_button:hover,
#chat .mes_edit_buttons .menu_button:hover,
#chat .mes_reasoning_actions .edit_button:hover,
#chat .favorite-toggle-icon:hover {
    opacity: 1 !important;
}

/* 🍺小鉛筆 */
.mes_buttons {
    top: 15px !important;
    right: 10px;
}

.mes_edit::before { 
  content: "\f56b";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900;
}

.extraMesButtonsHint::before {   
  content: "\f518";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900; 
}

.extraMesButtonsHint {
  padding-right: 8px;
}

/* 🍺正文edit按键 */
.mes_edit_buttons {
    filter: none;
    top: 12px !important;
    right: 14px;
    padding: 0;
}

/* 🍺幽靈圖標 */
.mes_ghost {
    top: 55px; 
    right: 16px;
}

/* 🍺訊息編號 */
.mesIDDisplay {
  top: 15px;
  font-size: 17px !important;
}

.mesIDDisplay::before {
  content: "Ch";
  margin-right: 8px;
  font-size: 15.5px !important;
}

/* 🍺Token */
.tokenCounterDisplay { 
  top: 46px;
  font-size: 12px !important;
}

.tokenCounterDisplay::before {
  content: "Tokens";
  margin-right: 8px;
  font-size: 9.5px !important;
}

/* 🍺計時 */
.mes_timer {
  top: 71px ;
  font-size: 12px;
}

.mes_timer::before {
  content: "Time";
  margin-right: 8px;
  font-size: 9.5px !important;
}

.mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    left: 8px;
}

/* 🪲小冰塊 */
.mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    padding: 1px 8px 2px 8px;
    opacity: 0.6 !important;
    transition: border 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.6s ease-out;
    font-family: var(--SecFont);
    border: 1px solid color-mix(in srgb, var(--ItemColor) 0%, transparent);
    color: var(--ItemColor) !important;
}

.mes_timer:hover, .tokenCounterDisplay:hover, .mesIDDisplay:hover {
  opacity: 1 !important;
  border: 1px solid color-mix(in srgb, var(--ItemColor) 40%, transparent);
  box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 60%, transparent) !important;
  transform: translateX(8px);
}

/*頂欄底欄圖標懸停*/
#quick-reply-rocket-button, #options_button, #extensionsMenuButton, #send_but, #top-settings-holder .drawer-icon {
    display: inline-block;
    transition: opacity 0.3s ease-in-out, filter 0.3s ease-in-out !important;
}
#quick-reply-rocket-button:is(:hover, .openDrawer), #options_button:is(:hover, .openDrawer),
#extensionsMenuButton:is(:hover, .openDrawer), #send_but:is(:hover, .openDrawer), #top-settings-holder .drawer-icon:is(:hover, .openIcon) {
    filter: drop-shadow(0 0 5px var(--ItemColor)) !important;
    opacity: 1 !important;
}

/* 🪲頂欄 */
#top-settings-holder .drawer-icon::before {
    content: "♛";
    font-family: "Font Awesome 6 Free" !important;
    font-weight: 900;
}
#top-settings-holder > .drawer:nth-child(even) .drawer-icon::before {
    content: "✦";
    font-family: "Font Awesome 6 Free" !important;
    font-weight: 900;
}

body.no-blur #top-bar, #top-bar {
    background-color: var(--TopBarColor) !important;
    border-radius: 0;
    box-shadow: none !important;
}

#top-bar .drawer-icon, 
.drawer-toggle .drawer-icon {
    font-size: var(--TopBarIconSize) !important;
    color: var(--TopBarIconColor) !important; 
    opacity: var(--TopBarIconOpacity);
}

/* 🪲底欄 */

/*底欄圖標 by @_nak.a.ri*/
/* 菜单 */
#options_button::before {
  content: "\f56b";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900;
  transform: scaleX(-1);
}

/* 扩展 */
#extensionsMenuButton::before {
    content: "♚";
}

/* 发送消息 */
#send_but::before {
  content: "\f56b";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900;
}

body.no-blur #send_form, #send_form {
    background-color: var(--TopBarColor) !important;
    border: none !important;
    outline: none !important;
    border-radius: 0 !important;
    border-top: var(--TopbarBorder) !important;
    padding: 2px 8px 3px 8px;
}

#rightSendForm>div, #leftSendForm>div {
    font-size: var(--BottomBarIconSize) !important;
    color: var(--TopBarIconColor) !important;
    opacity: var(--TopBarIconOpacity) !important;
}

#send_textarea::placeholder {
  color: transparent;
  opacity: 0;
}

/*消除底欄縫隙 by@_nak.a.ri*/
#form_sheld {
  margin: 0 auto !important;
}
/*修正版by咩野*/
body:not(.waifuMode) #sheld {
  top: var(--bottomFormBlockSize) !important;
  height: calc(100dvh - var(--bottomFormBlockSize)) !important;
  min-height: calc(100dvh - var(--bottomFormBlockSize)) !important;
}
/*🪲左右欄*/
#right-nav-panel, #left-nav-panel {
    background-color: var(--PanelColor) !important;
    border: none;
}
#left-nav-panel { box-shadow: 1px 0px 0 var(--PanelColor) !important; }
#right-nav-panel { box-shadow: -1px 0px 0 var(--PanelColor) !important; }

/* 手機端左右欄背景顏色 */
@media screen and (max-width: 768px) {
  #left-nav-panel, #right-nav-panel {
    background-color: var(--PanelColorPhone) !important; }
}
/* PC端左右欄佔滿全屏 */
@media screen and (min-width: 1025px) and (pointer: fine) {
  #left-nav-panel, #right-nav-panel {
    top: 0 !important;
    height: 100vh !important;
    max-height: 100vh !important; }
}

/*右欄角色管理*/
.group_select:hover,
.avatar-container.interactable:hover,
.bogus_folder_select:hover, .character_select:hover {
    background-color: transparent; 
    box-shadow: inset 0 0 8px var(--ItemColor);
    border-radius: var(--SmartThemeRadius);
}

.group_select,
.bogus_folder_select, .character_select {
  padding: 10px;
  border: 1px solid transparent;
  border-radius: var(--SmartThemeRadius) !important;
}

#rm_button_characters, #rm_button_panel_pin_div, #lm_button_panel_pin_div, #WI_button_panel_pin_div {
    font-size: 1.15em !important;
    opacity:  1;
    padding-bottom: 5px;
}


/*群組頁面*/
#rm_group_members,
#rm_group_add_members {
  background: transparent;
  border: none;
}
/* 角色收藏 */
.hotswap.avatars_inline {
    display: flex;
    flex-wrap: wrap;
    transition: all 1s ease;
    scrollbar-width: none;
}
.hotswap.avatars_inline::-webkit-scrollbar {
    display: none;
}
.hotswap.avatars_inline:hover {
    max-height: 300px;
    overflow: auto;
}

/*收藏角色頭像框 by @rech0_viixi 雙色盒子*/
.character_select.is_fav .avatar {
  outline: 3px double var(--ItemColor);
  border-radius: 2px !important;
}
.character_select.is_fav .ch_name {
  color: var(--ItemColor);
}

/*使用者角色選中頭像 by @mayonnaise58*/
.avatar-container.interactable.selected {
    background-color: transparent; 
    box-shadow: inset 0 0 8px var(--ItemColor);
    border-radius: var(--SmartThemeRadius) !important;
    border: none;
}
.avatar-container.interactable:hover {
    border-radius: calc(var(--SmartThemeRadius) + 2px);
    background-color: transparent !important;
    box-shadow: inset 0 0 8px var(--ItemColor);
}

/*角色管理按鈕*/
#charListFixedTop .rm_tag_filter .tag {
    background: transparent !important;
    color: var(--ItemColor);
    filter: none;
    opacity: 0.7;
    border: 0;
    box-shadow: inset 0 0 8px color-mix(in srgb, var(--ItemColor) 50%, transparent) !important;
}


.select2_choice_clickable_buttonstyle+span.select2-container .select2-selection__choice__display,
.select2_choice_clickable_buttonstyle+span.select2-container .select2-selection__choice__display:hover {
  background-color: transparent !important;
}
.select2-container--default .select2-selection--multiple .select2-selection__choice:hover {
    border: 1px solid color-mix(in srgb, var(--ItemColor) 60%, transparent) !important;
    box-shadow: inset 0 0 7px color-mix(in srgb, var(--ItemColor) 50%, transparent) !important;
}
.select2.select2-container .select2-selection__choice__remove {
  background-color: transparent !important;
}
/* 🪲預設 */
#completion_prompt_manager_list {
    background-color: transparent !important; 
    border: none;
    box-shadow: none !important;
}

/*預設條目樣式*/
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    padding: 8px;
    margin-bottom: 8px;
}
#completion_prompt_manager_list li [class*="fa-"] {
    color: color-mix(in srgb, var(--SmartThemeBodyColor) 35%, transparent) !important;
}
#completion_prompt_manager_list li > span:nth-child(3) span {
    color: var(--SmartThemeBodyColor) !important;
    opacity: 0.65 !important;
    transition: opacity 0.2s ease;
}
#completion_prompt_manager_list li > span:nth-child(3) span:hover {
    opacity: 0.8 !important;
}

/* 預設開啟條目 */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    background-color: color-mix(in srgb, var(--ItemColor) 5%, transparent) !important;
    border: 1px solid color-mix(in srgb, var(--ItemColor) 45%, transparent) !important;
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 35%, transparent);
}

/* 預設關閉條目 */
.completion_prompt_manager_prompt_disabled,
.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent) !important;    border: 1px solid transparent !important;
    box-shadow: none;
}



#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeBodyColor);
}

/*預設小字隱藏*/
#completion_prompt_manager_popup_edit > div .text_muted,
#completion_prompt_manager_popup_edit > h3,
#openai_settings .inline-drawer-header small, 
.toggle-description {
    display: none !important;
}
/*預設條目編輯版面*/
.completion_prompt_manager_popup_entry_form_control {
   margin-top: 3px; 
}
#completion_prompt_manager_popup {
   padding: 0;
}
#completion_prompt_manager_popup .completion_prompt_manager_popup_entry .completion_prompt_manager_popup_entry_form_footer {
    margin-top: 2px !important;
}
#completion_prompt_manager_popup .completion_prompt_manager_popup_entry .completion_prompt_manager_popup_entry_form_footer .menu_button {
    border: 1px solid color-mix(in srgb, var(--ItemColor) 30%, transparent) !important;
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 30%, transparent) !important;
    padding: 9px 11px !important;
}

/*預設頂部通知*/
.editable-slider-notification {
  font-size: 0;
  opacity: 0.4;
}

@media (min-width: 768px) {
  .editable-slider-notification::after {
    content: "✶-⊹ 𝔐𝔢𝔪𝔢𝔫𝔱𝔬 𝔐𝔬𝔯𝔦 ⊹-✶";
    font-size: 15px;
    color: var(--ItemColor);
  }
}

/* 預設標題 by @mdma_v10d*/
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
